// קובץ שנוצר אוטומטית – לא לערוך ידנית (npm run build)
export const ASSETS = {"/admin.html":{"type":"text/html; charset=utf-8","b64":false,"body":"<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"robots\" content=\"noindex, nofollow\" />\n  <title>ניהול – משחק הסקר</title>\n  <link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n<section id=\"v-login\" class=\"center-page\">\n  <form class=\"card\" id=\"f-login\" style=\"max-width:380px;width:100%;text-align:center\">\n    <h1 class=\"brand-title\" style=\"font-size:1.8rem\">ניהול</h1>\n    <input type=\"password\" id=\"pw\" placeholder=\"סיסמת ניהול\" />\n    <p class=\"error\" id=\"login-err\"></p>\n    <button class=\"btn primary\" style=\"width:100%\">כניסה</button>\n  </form>\n</section>\n\n<section id=\"v-main\" hidden>\n  <div class=\"wrap\">\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <h1 class=\"brand-title\">ניהול משחק הסקר</h1>\n      <button class=\"btn ghost\" id=\"btn-out\">יציאה</button>\n    </div>\n\n    <div class=\"card\">\n      <h2>יצירת קוד ללקוחה</h2>\n      <p class=\"muted\" style=\"margin-top:0\">אחרי שקיבלת העברה בנקאית – צרי קוד ושלחי ללקוחה יחד עם הקישור לאתר.</p>\n      <form id=\"f-code\" class=\"settings-grid\">\n        <label class=\"grow\" style=\"flex-direction:column;align-items:stretch\">שם / הערה (למשל: רחל כהן – שולם 23/11)\n          <input type=\"text\" id=\"c-label\" /></label>\n        <label style=\"flex-direction:column;align-items:stretch\">קוד (ריק = מספר אקראי)\n          <input type=\"text\" id=\"c-code\" class=\"ltr\" /></label>\n        <label style=\"flex-direction:column;align-items:stretch\">תוקף בימים (0 = ללא הגבלה)\n          <input type=\"number\" id=\"c-days\" value=\"30\" min=\"0\" /></label>\n        <label style=\"flex-direction:column;align-items:stretch\">מספר משחקים (0 = ללא הגבלה)\n          <input type=\"number\" id=\"c-max\" value=\"1\" min=\"0\" /></label>\n        <div style=\"align-self:end\"><button class=\"btn primary\">יצירת קוד</button></div>\n      </form>\n      <p class=\"error\" id=\"code-err\"></p>\n      <div id=\"new-code\" class=\"note\" hidden></div>\n    </div>\n\n    <div class=\"card\">\n      <h2>הקודים</h2>\n      <div style=\"overflow:auto\"><table class=\"admin\" id=\"codes\"></table></div>\n    </div>\n\n    <div class=\"card\">\n      <h2>מאגר השאלות הכללי</h2>\n      <p class=\"muted\" style=\"margin-top:0\">זה המאגר שכל לקוחה רואה כברירת מחדל. שורה לכל שאלה. לשאלה עם תשובות קבועות (לא שמות) כתבי בסוף: <code>| תשובה1, תשובה2, תשובה3</code></p>\n      <textarea id=\"bank\" rows=\"20\" style=\"font-size:1rem;line-height:1.7\"></textarea>\n      <div class=\"row\" style=\"margin-top:10px\">\n        <button class=\"btn primary\" id=\"btn-bank\">שמירת המאגר</button>\n        <span id=\"bank-msg\" class=\"muted\"></span>\n      </div>\n    </div>\n  </div>\n</section>\n\n<script>\nconst $ = (s) => document.querySelector(s);\nconst esc = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nlet pw = sessionStorage.getItem('seker_admin') || '';\n\nasync function api(path, method = 'GET', body) {\n  const r = await fetch(path, { method, headers: { 'content-type': 'application/json', 'x-admin-password': pw }, body: body ? JSON.stringify(body) : undefined });\n  const d = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(d.error || 'שגיאה');\n  return d;\n}\n\n$('#f-login').onsubmit = async (e) => {\n  e.preventDefault();\n  pw = $('#pw').value;\n  try { await start(); sessionStorage.setItem('seker_admin', pw); }\n  catch (er) { $('#login-err').textContent = er.message; }\n};\n$('#btn-out').onclick = () => { sessionStorage.removeItem('seker_admin'); location.reload(); };\n\nasync function start() {\n  await loadCodes();\n  await loadBank();\n  $('#v-login').hidden = true;\n  $('#v-main').hidden = false;\n}\n\nconst fmt = (t) => t ? new Date(t).toLocaleDateString('he-IL') : '—';\n\nasync function loadCodes() {\n  const { codes } = await api('/api/admin/codes');\n  $('#codes').innerHTML = `<tr><th>קוד</th><th>שם / הערה</th><th>נוצר</th><th>בתוקף עד</th><th>משחקים</th><th>מצב</th><th></th></tr>` +\n    codes.map(c => {\n      const expired = c.expires_at && c.expires_at < Date.now();\n      return `<tr data-code=\"${esc(c.code)}\">\n        <td><span class=\"code-txt\">${esc(c.code)}</span></td>\n        <td>${esc(c.label)}</td>\n        <td>${fmt(c.created_at)}</td>\n        <td>${c.expires_at ? fmt(c.expires_at) + (expired ? ' <span class=\"tag\" style=\"background:#fbeaea;color:#c93c3c\">פג</span>' : '') : 'ללא הגבלה'}</td>\n        <td>${c.games_used}${c.max_games ? ' / ' + c.max_games : ''}</td>\n        <td>${c.active ? '<span class=\"tag\">פעיל</span>' : '<span class=\"tag opt\">מושבת</span>'}</td>\n        <td class=\"row\">\n          <button class=\"btn small\" data-a=\"toggle\">${c.active ? 'השבתה' : 'הפעלה'}</button>\n          <button class=\"btn small\" data-a=\"days\">+ימים</button>\n          <button class=\"btn small\" data-a=\"games\">שינוי משחקים</button>\n          <button class=\"btn small danger\" data-a=\"del\">מחיקה</button>\n        </td></tr>`;\n    }).join('');\n  window._codes = Object.fromEntries(codes.map(c => [c.code, c]));\n}\n\n$('#codes').onclick = async (e) => {\n  const a = e.target.dataset.a; if (!a) return;\n  const code = e.target.closest('tr').dataset.code;\n  const c = window._codes[code];\n  try {\n    if (a === 'toggle') await api('/api/admin/codes/' + code, 'PATCH', { active: !c.active });\n    if (a === 'days') { const d = prompt('כמה ימים להוסיף? (0 = ללא הגבלה)', '30'); if (d === null) return; await api('/api/admin/codes/' + code, 'PATCH', { addDays: Number(d) }); }\n    if (a === 'games') { const d = prompt('מספר משחקים כולל (0 = ללא הגבלה). כרגע נוצלו ' + c.games_used, c.max_games || 0); if (d === null) return; await api('/api/admin/codes/' + code, 'PATCH', { maxGames: Number(d) }); }\n    if (a === 'del') { if (!confirm('למחוק את הקוד ' + code + '?')) return; await api('/api/admin/codes/' + code, 'DELETE'); }\n    loadCodes();\n  } catch (er) { alert(er.message); }\n};\n\n$('#f-code').onsubmit = async (e) => {\n  e.preventDefault();\n  $('#code-err').textContent = '';\n  try {\n    const r = await api('/api/admin/codes', 'POST', { label: $('#c-label').value, code: $('#c-code').value, days: $('#c-days').value, maxGames: $('#c-max').value });\n    $('#new-code').hidden = false;\n    $('#new-code').innerHTML = `✓ נוצר הקוד <span class=\"code-txt\">${esc(r.code)}</span><br>טקסט לשליחה ללקוחה:<br><textarea rows=\"3\" onclick=\"this.select()\">שלום! הקישור למשחק: ${location.origin}\\nקוד הכניסה שלך: ${r.code}</textarea>`;\n    $('#c-label').value = ''; $('#c-code').value = '';\n    loadCodes();\n  } catch (er) { $('#code-err').textContent = er.message; }\n};\n\nasync function loadBank() {\n  const { questions } = await api('/api/admin/bank');\n  $('#bank').value = questions.map(q => q.type === 'options' ? `${q.text} | ${q.options.join(', ')}` : q.text).join('\\n');\n}\n$('#btn-bank').onclick = async () => {\n  const questions = $('#bank').value.split('\\n').map(l => l.trim()).filter(Boolean).map(l => {\n    const [t, o] = l.split('|');\n    return o ? { text: t.trim(), type: 'options', options: o.split(',').map(s => s.trim()).filter(Boolean) } : { text: t.trim(), type: 'names' };\n  });\n  try {\n    const r = await api('/api/admin/bank', 'PUT', { questions });\n    $('#bank-msg').textContent = `✓ נשמרו ${r.questions.length} שאלות`;\n    loadBank();\n  } catch (er) { alert(er.message); }\n};\n\nif (pw) start().catch(() => {});\n</script>\n</body>\n</html>\n"},"/app.js":{"type":"text/javascript; charset=utf-8","b64":false,"body":"// ===== משחק הסקר – צד הדפדפן =====\nconst $ = (s) => document.querySelector(s);\nconst esc = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst MAX = 15;\n\nlet token = localStorage.getItem('seker_token') || '';\nlet me = null;\nlet questions = []; // {text,type,options,on}\n\nasync function api(path, opts = {}) {\n  const res = await fetch(path, {\n    method: opts.method || 'GET',\n    headers: { 'content-type': 'application/json', authorization: 'Bearer ' + token },\n    body: opts.body ? JSON.stringify(opts.body) : undefined,\n  });\n  const data = await res.json().catch(() => ({}));\n  if (res.status === 401 && path !== '/api/login') {\n    logout();\n    throw new Error(data.error || 'צריך להיכנס מחדש');\n  }\n  if (!res.ok) throw new Error(data.error || 'שגיאה');\n  return data;\n}\n\nfunction show(view) {\n  for (const v of ['login', 'setup', 'game']) $('#view-' + v).hidden = v !== view;\n}\n\nfunction logout() {\n  token = '';\n  localStorage.removeItem('seker_token');\n  localStorage.removeItem('seker_game');\n  stopPolling();\n  show('login');\n}\n\n// ---------- כניסה ----------\n$('#login-form').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  $('#login-error').textContent = '';\n  try {\n    const r = await api('/api/login', { method: 'POST', body: { code: $('#login-code').value } });\n    token = r.token;\n    localStorage.setItem('seker_token', token);\n    await openSetup();\n  } catch (er) {\n    $('#login-error').textContent = er.message;\n  }\n});\n$('#btn-logout').onclick = logout;\n\n// ---------- הכנת משחק ----------\nasync function openSetup() {\n  me = await api('/api/me');\n  $('#setup-sub').textContent =\n    (me.label ? me.label + ' · ' : '') + (me.gamesLeft == null ? 'ללא הגבלת משחקים' : `נותרו ${me.gamesLeft} משחקים בקוד`);\n  $('#btn-resume').hidden = !localStorage.getItem('seker_game');\n  renderPlayers();\n  const r = await api('/api/questions');\n  setQuestions(r.questions, r.custom);\n  show('setup');\n}\n\n$('#btn-resume').onclick = () => openGame(Number(localStorage.getItem('seker_game')));\n\nfunction loadPlayers() {\n  try {\n    return JSON.parse(localStorage.getItem('seker_players')) || [];\n  } catch {\n    return [];\n  }\n}\nfunction savePlayers() {\n  const list = [];\n  for (let i = 0; i < MAX; i++) {\n    list.push({ name: $(`#pn-${i}`).value, phone: $(`#pp-${i}`).value });\n  }\n  localStorage.setItem('seker_players', JSON.stringify(list));\n  const n = list.filter((p) => p.name.trim()).length;\n  $('#players-count').textContent = `${n} משתתפות`;\n}\nfunction renderPlayers() {\n  const saved = loadPlayers();\n  let h = '<div class=\"head\"></div><div class=\"head\">שם</div><div class=\"head ph\">טלפון</div>';\n  for (let i = 0; i < MAX; i++) {\n    const p = saved[i] || {};\n    h += `<div class=\"num\">${i + 1}</div>\n      <input type=\"text\" id=\"pn-${i}\" value=\"${esc(p.name)}\" placeholder=\"שם משתתפת ${i + 1}\" />\n      <input type=\"tel\" id=\"pp-${i}\" class=\"ltr phone-cell\" value=\"${esc(p.phone)}\" placeholder=\"050-0000000\" />`;\n  }\n  $('#players-grid').innerHTML = h;\n  $('#players-grid').oninput = savePlayers;\n  savePlayers();\n}\n$('#btn-clear-players').onclick = () => {\n  if (!confirm('לנקות את כל השמות והטלפונים?')) return;\n  localStorage.removeItem('seker_players');\n  renderPlayers();\n};\n\nfunction setQuestions(list, custom) {\n  questions = list.map((q) => ({ ...q, on: true }));\n  $('#q-saved').textContent = custom ? 'מוצג המאגר האישי ששמרת.' : 'מוצג מאגר השאלות הכללי.';\n  renderQuestions();\n}\n\nfunction renderQuestions() {\n  $('#q-list').innerHTML = questions\n    .map(\n      (q, i) => `\n    <div class=\"q-item ${q.on ? '' : 'off'}\" data-i=\"${i}\">\n      <input type=\"checkbox\" data-f=\"on\" ${q.on ? 'checked' : ''} title=\"לכלול במשחק\" />\n      <div class=\"q-edit\">\n        <input type=\"text\" data-f=\"text\" value=\"${esc(q.text)}\" />\n        <div class=\"row\">\n          <select data-f=\"type\" style=\"width:auto\">\n            <option value=\"names\" ${q.type === 'names' ? 'selected' : ''}>התשובות: שמות המשתתפות</option>\n            <option value=\"options\" ${q.type === 'options' ? 'selected' : ''}>התשובות: אפשרויות קבועות</option>\n          </select>\n          ${\n            q.type === 'options'\n              ? `<input type=\"text\" class=\"grow\" data-f=\"options\" value=\"${esc(q.options.join(', '))}\" placeholder=\"אפשרויות מופרדות בפסיק: קפה, תה, שניהם\" style=\"width:auto\" />`\n              : ''\n          }\n        </div>\n      </div>\n      <button class=\"btn small danger\" data-del title=\"מחיקה\">✕</button>\n    </div>`\n    )\n    .join('');\n  updateQCount();\n}\n\nfunction updateQCount() {\n  const on = questions.filter((q) => q.on).length;\n  $('#q-count').textContent = `נבחרו ${on} מתוך ${questions.length} שאלות`;\n}\n\n$('#q-list').addEventListener('input', (e) => {\n  const item = e.target.closest('.q-item');\n  if (!item) return;\n  const q = questions[item.dataset.i];\n  const f = e.target.dataset.f;\n  if (f === 'text') q.text = e.target.value;\n  if (f === 'options') q.options = e.target.value.split(',').map((s) => s.trim()).filter(Boolean);\n});\n$('#q-list').addEventListener('change', (e) => {\n  const item = e.target.closest('.q-item');\n  if (!item) return;\n  const q = questions[item.dataset.i];\n  const f = e.target.dataset.f;\n  if (f === 'on') {\n    q.on = e.target.checked;\n    item.classList.toggle('off', !q.on);\n    updateQCount();\n  }\n  if (f === 'type') {\n    q.type = e.target.value;\n    if (q.type === 'options' && !q.options.length) q.options = ['כן', 'לא'];\n    renderQuestions();\n  }\n});\n$('#q-list').addEventListener('click', (e) => {\n  if (!e.target.matches('[data-del]')) return;\n  const i = Number(e.target.closest('.q-item').dataset.i);\n  questions.splice(i, 1);\n  renderQuestions();\n});\n\n$('#btn-all').onclick = () => (questions.forEach((q) => (q.on = true)), renderQuestions());\n$('#btn-none').onclick = () => (questions.forEach((q) => (q.on = false)), renderQuestions());\n$('#btn-random').onclick = () => {\n  const n = Math.max(1, Number($('#random-n').value) || 10);\n  const idx = shuffle(questions.map((_, i) => i)).slice(0, n);\n  questions.forEach((q, i) => (q.on = idx.includes(i)));\n  renderQuestions();\n};\n$('#btn-add-q').onclick = () => {\n  questions.unshift({ text: '', type: 'names', options: [], on: true });\n  renderQuestions();\n  $('#q-list input[data-f=text]').focus();\n};\n$('#btn-save-q').onclick = async () => {\n  try {\n    const r = await api('/api/questions', { method: 'PUT', body: { questions } });\n    const onTexts = new Set(questions.filter((q) => q.on).map((q) => q.text.trim()));\n    setQuestions(r.questions, true);\n    questions.forEach((q) => (q.on = onTexts.has(q.text)));\n    renderQuestions();\n    $('#q-saved').textContent = '✓ השאלות נשמרו. בפעם הבאה שתיכנסי עם הקוד הן יופיעו כך.';\n  } catch (er) {\n    alert(er.message);\n  }\n};\n$('#btn-reset-q').onclick = async () => {\n  if (!confirm('להחזיר את מאגר השאלות הכללי? השינויים ששמרת יימחקו.')) return;\n  const r = await api('/api/questions', { method: 'DELETE' });\n  setQuestions(r.questions, false);\n};\n\nfunction shuffle(a) {\n  for (let i = a.length - 1; i > 0; i--) {\n    const j = Math.floor(Math.random() * (i + 1));\n    [a[i], a[j]] = [a[j], a[i]];\n  }\n  return a;\n}\n\n$('#btn-create').onclick = async () => {\n  $('#setup-error').textContent = '';\n  const players = loadPlayers().filter((p) => p.name && p.name.trim());\n  let qs = questions.filter((q) => q.on && q.text.trim());\n  if ($('#set-shuffle').checked) qs = shuffle([...qs]);\n  // שאלות עם יותר אפשרויות ממה שאפשר להקיש\n  const bad = qs.find((q) => q.type === 'options' && q.options.length < 2);\n  if (bad) return ($('#setup-error').textContent = `בשאלה \"${bad.text}\" צריך לפחות 2 אפשרויות`);\n  try {\n    const r = await api('/api/games', {\n      method: 'POST',\n      body: {\n        players,\n        questions: qs,\n        settings: {\n          timerSec: Number($('#set-timer').value) || 0,\n          allowSelfVote: $('#set-self').checked,\n          autoReveal: $('#set-auto').checked,\n          showVoters: $('#set-voters').checked,\n        },\n      },\n    });\n    localStorage.setItem('seker_game', r.id);\n    openGame(r.id);\n  } catch (er) {\n    $('#setup-error').textContent = er.message;\n  }\n};\n\n// ---------- מסך המשחק – במה עם וילון ----------\nlet gameId = null;\nlet pollTimer = null;\nlet tickTimer = null;\nlet state = null;\nlet clockOffset = 0;\nlet lastMainKey = '';\nlet lastControlsKey = '';\nlet sceneKey = ''; // lobby | q<index> | ended\nlet transition = null; // טיימר של מעבר וילון פעיל\nlet lastBeepSec = null;\nlet soundOn = localStorage.getItem('seker_sound') !== 'off';\n\nconst CURTAIN_MS = 1100; // משך סגירה/פתיחה של הווילון\nconst HOLD_MS = 1300; // כמה זמן הווילון נשאר סגור עם \"שאלה N\"\n\nfunction stopPolling() {\n  clearInterval(pollTimer);\n  clearInterval(tickTimer);\n  clearTimeout(transition);\n  transition = null;\n}\n\nasync function openGame(id) {\n  gameId = id;\n  if (!me) me = await api('/api/me');\n  $('#dial-info').innerHTML = me.phoneInfo\n    ? `☎ להצבעה התקשרו: <b>${esc(me.phoneInfo)}</b>`\n    : '☎ להצבעה התקשרו למספר המשחק';\n  lastMainKey = lastControlsKey = sceneKey = '';\n  $('#game-main').innerHTML = '';\n  setCurtain(true, true);\n  show('game');\n  stopPolling();\n  await refresh();\n  pollTimer = setInterval(refresh, 1000);\n  tickTimer = setInterval(tick, 200);\n}\n\nasync function refresh() {\n  try {\n    const s = await api(`/api/games/${gameId}`);\n    clockOffset = s.serverNow - Date.now();\n    state = s;\n    render();\n  } catch (er) {\n    if (er.message.includes('לא נמצא')) {\n      localStorage.removeItem('seker_game');\n      stopPolling();\n      openSetup();\n    }\n  }\n}\n\nasync function act(action) {\n  try {\n    state = await api(`/api/games/${gameId}/action`, { method: 'POST', body: { action } });\n    render();\n  } catch (er) {\n    alert(er.message);\n  }\n}\n\n// ---- וילון ----\nfunction setCurtain(closed, instant = false) {\n  const st = $('#stage');\n  if (instant) st.classList.add('no-anim');\n  st.classList.toggle('closed', closed);\n  if (instant) requestAnimationFrame(() => requestAnimationFrame(() => st.classList.remove('no-anim')));\n}\n\nfunction curtainLabel(html) {\n  $('#curtain-label').innerHTML = html;\n}\n\n// מעבר סצנה: סוגרים וילון → מציגים כיתוב → מחליפים תוכן → פותחים\nfunction changeScene(label, onSwap) {\n  clearTimeout(transition);\n  const wasClosed = $('#stage').classList.contains('closed');\n  curtainLabel(label);\n  setCurtain(true);\n  transition = setTimeout(\n    () => {\n      onSwap();\n      setCurtain(false);\n      transition = null;\n    },\n    (wasClosed ? 0 : CURTAIN_MS) + HOLD_MS\n  );\n}\n\nfunction lobbyLabel(s) {\n  const g = s.game;\n  const conn = s.players.filter((p) => p.connected).length;\n  return `\n    <div class=\"marquee\">משחק הסקר</div>\n    <div class=\"curtain-sub\">מתקשרות ומצטרפות! קוד משחק: <b>${esc(g.pin)}</b></div>\n    <div class=\"lobby-chips\">${s.players\n      .map((p) => `<span class=\"lchip ${p.connected ? 'on' : ''}\"><b>${p.num}</b> ${esc(p.name)}</span>`)\n      .join('')}</div>\n    <div class=\"curtain-sub small\">${conn} מתוך ${s.players.length} מחוברות · ${g.total} שאלות מחכות לכן</div>`;\n}\n\nfunction render() {\n  const s = state;\n  const g = s.game;\n  $('#game-pin').textContent = g.pin;\n  renderControls();\n\n  const newScene = g.phase === 'lobby' ? 'lobby' : g.phase === 'ended' ? 'ended' : 'q' + g.qIndex;\n\n  if (newScene !== sceneKey) {\n    const first = sceneKey === '';\n    sceneKey = newScene;\n    lastMainKey = '';\n    lastBeepSec = null;\n    if (newScene === 'lobby') {\n      clearTimeout(transition);\n      $('#game-main').innerHTML = '';\n      curtainLabel(lobbyLabel(s));\n      setCurtain(true, first);\n      return;\n    }\n    if (newScene === 'ended') {\n      changeScene(`<div class=\"marquee\">🎊 סוף המשחק 🎊</div><div class=\"curtain-sub\">ועכשיו... הסיכום!</div>`, () => drawMain(true));\n      return;\n    }\n    changeScene(\n      `<div class=\"curtain-sub\">שאלה</div><div class=\"marquee big\">${g.qIndex + 1}</div><div class=\"curtain-sub\">מתוך ${g.total}</div>`,\n      () => drawMain(true)\n    );\n    return;\n  }\n\n  if (newScene === 'lobby') return curtainLabel(lobbyLabel(s));\n  if (!transition) drawMain(false);\n}\n\nfunction drawMain(fresh) {\n  const s = state;\n  const g = s.game;\n  let mainKey, html;\n\n  if (g.phase === 'question') {\n    const q = s.question;\n    html = `\n      <div class=\"q-head\">\n        <div class=\"q-counter\">שאלה ${g.qIndex + 1} מתוך ${g.total}</div>\n        ${g.settings.timerSec ? timerSvg() : ''}\n      </div>\n      <div class=\"q-title\">${esc(q.text)}</div>\n      <div class=\"options\">${q.options.map((o) => `<div class=\"opt\"><span class=\"n\">${o.n}</span><span class=\"lbl\">${esc(o.label)}</span></div>`).join('')}</div>\n      <div class=\"status-line\">\n        <span class=\"vote-count\">הצביעו <b>${s.votesCount}</b> מתוך ${s.players.length}</span>\n        <span class=\"hint\">מקישים את המספר ואחריו סולמית #</span>\n      </div>\n      ${\n        g.settings.showVoters\n          ? `<div class=\"voters\">${s.players.map((p) => `<span class=\"chip ${p.voted ? 'on' : ''}\">${esc(p.name)}</span>`).join('')}</div>`\n          : ''\n      }`;\n    mainKey = html;\n  } else if (g.phase === 'results') {\n    const res = s.results || [];\n    const top = res[0]?.count || 0;\n    const winners = top ? res.filter((r) => r.count === top) : [];\n    const max = Math.max(1, top);\n    mainKey = `results-${g.qIndex}-${JSON.stringify(res)}`;\n    html = `\n      <div class=\"q-counter\">שאלה ${g.qIndex + 1} מתוך ${g.total} · ${s.votesCount} הצבעות</div>\n      <div class=\"q-title small\">${esc(s.question.text)}</div>\n      <div class=\"winner-banner\">${\n        winners.length === 0\n          ? 'אף אחת לא הצביעה 🤷‍♀️'\n          : winners.length === 1\n          ? `<span class=\"crown\">👑</span><span class=\"wname\">${esc(winners[0].label)}</span>`\n          : `<span class=\"crown\">👑</span><span class=\"wname\">תיקו! ${winners.map((w) => esc(w.label)).join(' · ')}</span>`\n      }</div>\n      <div class=\"bars\">${res\n        .filter((r) => r.count > 0)\n        .map(\n          (r) => `<div class=\"bar-row ${r.count === top && top ? 'win' : ''}\">\n          <span class=\"lbl\">${esc(r.label)}</span>\n          <div class=\"bar-track\"><div class=\"bar-fill\" data-w=\"${(r.count / max) * 100}\"></div></div>\n          <span class=\"cnt\">${r.count}</span></div>`\n        )\n        .join('')}</div>\n      ${\n        res.some((r) => r.count === 0)\n          ? `<p class=\"no-votes\">ללא קולות: ${res.filter((r) => r.count === 0).map((r) => esc(r.label)).join(' · ')}</p>`\n          : ''\n      }`;\n  } else if (g.phase === 'ended') {\n    mainKey = 'ended' + JSON.stringify(s.summary);\n    html = `\n      <div class=\"q-title\">🏆 הסיכום הגדול 🏆</div>\n      <div class=\"summary\">${(s.summary || [])\n        .map(\n          (r, i) => `<div class=\"sum-row\" style=\"animation-delay:${i * 0.08}s\"><span>${esc(r.text)}</span><span>${\n            r.winners.length ? `<b>${r.winners.map(esc).join(' · ')}</b> <small>(${r.top})</small>` : '<small>אין הצבעות</small>'\n          }</span></div>`\n        )\n        .join('')}</div>`;\n  } else return;\n\n  if (mainKey === lastMainKey) return;\n  const isNewResults = g.phase === 'results' && !lastMainKey.startsWith(`results-${g.qIndex}-`);\n  $('#game-main').innerHTML = html;\n  $('#game-main').classList.toggle('enter', fresh);\n  const fills = document.querySelectorAll('.bar-fill');\n  if (isNewResults) {\n    requestAnimationFrame(() => requestAnimationFrame(() => fills.forEach((f) => (f.style.width = f.dataset.w + '%'))));\n    if ((s.results || [])[0]?.count) {\n      confetti();\n      sound('fanfare');\n    }\n  } else fills.forEach((f) => ((f.style.transition = 'none'), (f.style.width = f.dataset.w + '%')));\n  lastMainKey = mainKey;\n  tick();\n}\n\n// ---- טיימר עגול ----\nconst R = 52;\nconst CIRC = 2 * Math.PI * R;\nfunction timerSvg() {\n  return `<div class=\"timer-ring\" id=\"timer\">\n    <svg viewBox=\"0 0 120 120\"><circle class=\"track\" cx=\"60\" cy=\"60\" r=\"${R}\"/><circle class=\"prog\" id=\"timer-prog\" cx=\"60\" cy=\"60\" r=\"${R}\"\n      stroke-dasharray=\"${CIRC}\" stroke-dashoffset=\"0\"/></svg>\n    <span class=\"num\" id=\"timer-num\"></span></div>`;\n}\n\nfunction tick() {\n  const el = $('#timer');\n  if (!el || !state) return;\n  const g = state.game;\n  if (!g.settings.timerSec || g.phase !== 'question') return;\n  const total = g.settings.timerSec * 1000;\n  const leftMs = Math.min(total, Math.max(0, g.qStartedAt + total - (Date.now() + clockOffset)));\n  const left = Math.ceil(leftMs / 1000);\n  $('#timer-prog').style.strokeDashoffset = String(CIRC * (1 - leftMs / total));\n  $('#timer-num').textContent = left > 0 ? left : '⏰';\n  el.classList.toggle('low', left <= 5 && left > 0);\n  el.classList.toggle('done', left === 0);\n  if (left !== lastBeepSec) {\n    if (lastBeepSec !== null && left <= 5 && left > 0) sound('tick');\n    if (lastBeepSec !== null && lastBeepSec > 0 && left === 0) sound('buzz');\n    lastBeepSec = left;\n  }\n}\n\n// ---- צלילים (נוצרים בדפדפן, בלי קבצים) ----\nlet audioCtx = null;\nfunction sound(kind) {\n  if (!soundOn) return;\n  try {\n    audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();\n    const t = audioCtx.currentTime;\n    const note = (freq, start, dur, type = 'sine', vol = 0.2) => {\n      const o = audioCtx.createOscillator();\n      const gn = audioCtx.createGain();\n      o.type = type;\n      o.frequency.value = freq;\n      gn.gain.setValueAtTime(vol, t + start);\n      gn.gain.exponentialRampToValueAtTime(0.001, t + start + dur);\n      o.connect(gn).connect(audioCtx.destination);\n      o.start(t + start);\n      o.stop(t + start + dur);\n    };\n    if (kind === 'tick') note(880, 0, 0.12, 'square', 0.08);\n    if (kind === 'buzz') (note(220, 0, 0.5, 'sawtooth', 0.12), note(165, 0.05, 0.6, 'sawtooth', 0.1));\n    if (kind === 'fanfare') [523, 659, 784, 1047].forEach((f, i) => note(f, i * 0.12, i === 3 ? 0.6 : 0.18, 'triangle', 0.15));\n  } catch {}\n}\n\n// ---- קונפטי ----\nfunction confetti() {\n  const box = $('#confetti');\n  const colors = ['#f6c453', '#e94f6a', '#9b5de5', '#00bbf9', '#00f5d4', '#ffffff'];\n  let h = '';\n  for (let i = 0; i < 90; i++) {\n    const left = Math.random() * 100;\n    const delay = Math.random() * 0.6;\n    const dur = 2.2 + Math.random() * 1.8;\n    const size = 6 + Math.random() * 8;\n    const rot = Math.random() * 360;\n    h += `<i style=\"left:${left}%;width:${size}px;height:${size * 0.45}px;background:${colors[i % colors.length]};animation-delay:${delay}s;animation-duration:${dur}s;transform:rotate(${rot}deg)\"></i>`;\n  }\n  box.innerHTML = h;\n  setTimeout(() => (box.innerHTML = ''), 4500);\n}\n\nfunction renderControls() {\n  const g = state.game;\n  const last = g.qIndex + 1 >= g.total;\n  const B = (a, label, cls = '') => `<button class=\"btn ${cls}\" data-act=\"${a}\">${label}</button>`;\n  let h = '';\n  if (g.phase === 'lobby') h = B('start', 'הרמת המסך ▶', 'primary big') + B('setup', 'חזרה להכנה', 'ghost');\n  else if (g.phase === 'question')\n    h = B('reveal', 'הצגת התוצאות', 'primary big') + (g.qIndex > 0 ? B('prev', '→ שאלה קודמת') : '') + B('next', 'דילוג') + B('end', 'סיום המשחק', 'danger');\n  else if (g.phase === 'results')\n    h =\n      B('next', last ? 'סיום וסיכום 🎊' : 'השאלה הבאה ←', 'primary big') +\n      (g.qIndex > 0 ? B('prev', '→ שאלה קודמת') : '') +\n      B('reopen', 'פתיחה מחדש להצבעה') +\n      B('restart_question', 'איפוס ההצבעות') +\n      B('end', 'סיום המשחק', 'danger');\n  else h = B('setup', 'משחק חדש', 'primary big');\n  h += B('sound', soundOn ? '🔊' : '🔇', 'ghost') + B('fullscreen', '⛶ מסך מלא', 'ghost') + B('sim', '📱 סימולטור', 'ghost');\n  if (h === lastControlsKey) return;\n  lastControlsKey = h;\n  $('#controls').innerHTML = h;\n}\n\n$('#controls').addEventListener('click', (e) => {\n  const a = e.target.closest('[data-act]')?.dataset.act;\n  if (!a) return;\n  if (a === 'setup') {\n    if (state.game.phase !== 'ended' && !confirm('לחזור למסך ההכנה? המשחק הנוכחי יישאר פתוח עד שתיצרי משחק חדש.')) return;\n    stopPolling();\n    return openSetup();\n  }\n  if (a === 'sound') {\n    soundOn = !soundOn;\n    localStorage.setItem('seker_sound', soundOn ? 'on' : 'off');\n    if (soundOn) sound('tick');\n    return renderControls();\n  }\n  if (a === 'fullscreen') return document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen();\n  if (a === 'sim') return window.open(`/sim.html?game=${gameId}`, '_blank');\n  if (a === 'end' && !confirm('לסיים את המשחק?')) return;\n  if (a === 'restart_question' && !confirm('למחוק את כל ההצבעות לשאלה הזו?')) return;\n  sound('none'); // פותח את מערכת הקול של הדפדפן אחרי לחיצה\n  act(a);\n});\n\ndocument.addEventListener('keydown', (e) => {\n  if ($('#view-game').hidden || !state || e.target.matches('input, textarea')) return;\n  if (e.key === ' ' || e.key === 'Enter') {\n    const p = state.game.phase;\n    e.preventDefault();\n    if (p === 'lobby') act('start');\n    else if (p === 'question') act('reveal');\n    else if (p === 'results') act('next');\n  }\n});\n\n// ---------- התחלה ----------\n(async function init() {\n  if (!token) return show('login');\n  try {\n    const gid = Number(localStorage.getItem('seker_game'));\n    if (gid) {\n      await openGame(gid);\n    } else await openSetup();\n  } catch {\n    show('login');\n  }\n})();\n"},"/index.html":{"type":"text/html; charset=utf-8","b64":false,"body":"<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"robots\" content=\"noindex, nofollow\" />\n  <title>משחק הסקר</title>\n  <link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n\n<!-- ===== כניסה עם קוד ===== -->\n<section id=\"view-login\" class=\"center-page\" hidden>\n  <div class=\"card\" style=\"max-width:420px;width:100%;text-align:center\">\n    <h1 class=\"brand-title\">משחק הסקר</h1>\n    <p class=\"sub\">הקישי את הקוד שקיבלת כדי להתחיל</p>\n    <form id=\"login-form\">\n      <input id=\"login-code\" type=\"text\" class=\"ltr\" placeholder=\"קוד כניסה\" autocomplete=\"off\" style=\"text-align:center;font-size:1.4rem;letter-spacing:3px\" />\n      <p class=\"error\" id=\"login-error\"></p>\n      <button class=\"btn primary big\" style=\"width:100%\">כניסה</button>\n    </form>\n  </div>\n</section>\n\n<!-- ===== הכנת משחק ===== -->\n<section id=\"view-setup\" hidden>\n  <div class=\"wrap\">\n    <div class=\"row\" style=\"justify-content:space-between;margin-bottom:10px\">\n      <div>\n        <h1 class=\"brand-title\">הכנת משחק</h1>\n        <p class=\"sub\" id=\"setup-sub\"></p>\n      </div>\n      <div class=\"row\">\n        <button class=\"btn ghost\" id=\"btn-resume\" hidden>חזרה למשחק הפתוח</button>\n        <button class=\"btn ghost\" id=\"btn-logout\">יציאה</button>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <h2><span class=\"step\">1</span>המשתתפות (עד 15)</h2>\n      <p class=\"muted\" style=\"margin-top:0\">כל משתתפת מקבלת מספר. בטלפון היא תקיש את המספר של מי שהיא בוחרת. טלפון: מומלץ, כדי שהמערכת תזהה אותה אוטומטית כשהיא מתקשרת.</p>\n      <div class=\"players-grid\" id=\"players-grid\"></div>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <button class=\"btn small\" id=\"btn-clear-players\">ניקוי הרשימה</button>\n        <span class=\"muted\" id=\"players-count\"></span>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <h2><span class=\"step\">2</span>השאלות</h2>\n      <div class=\"row q-tools\">\n        <button class=\"btn small\" id=\"btn-all\">סימון הכל</button>\n        <button class=\"btn small\" id=\"btn-none\">ביטול הכל</button>\n        <button class=\"btn small\" id=\"btn-random\">בחירה אקראית של</button>\n        <input type=\"number\" id=\"random-n\" value=\"15\" min=\"1\" style=\"width:80px\" />\n        <button class=\"btn small\" id=\"btn-add-q\">+ הוספת שאלה</button>\n        <span class=\"grow\"></span>\n        <button class=\"btn small\" id=\"btn-save-q\">שמירת השאלות שלי</button>\n        <button class=\"btn small ghost\" id=\"btn-reset-q\">החזרת מאגר ברירת המחדל</button>\n      </div>\n      <p class=\"muted\" id=\"q-count\" style=\"margin:0 0 8px\"></p>\n      <div class=\"q-list\" id=\"q-list\"></div>\n      <p class=\"muted\" id=\"q-saved\" style=\"margin:8px 0 0\"></p>\n    </div>\n\n    <div class=\"card\">\n      <h2><span class=\"step\">3</span>הגדרות</h2>\n      <div class=\"settings-grid\">\n        <label>טיימר לכל שאלה (שניות, 0 = בלי)\n          <input type=\"number\" id=\"set-timer\" value=\"30\" min=\"0\" max=\"600\" style=\"width:90px\" />\n        </label>\n        <label><input type=\"checkbox\" id=\"set-shuffle\" /> ערבוב סדר השאלות</label>\n        <label><input type=\"checkbox\" id=\"set-self\" checked /> מותר להצביע לעצמך</label>\n        <label><input type=\"checkbox\" id=\"set-auto\" /> הצגת תוצאות אוטומטית כשכולן הצביעו / הזמן נגמר</label>\n        <label><input type=\"checkbox\" id=\"set-voters\" checked /> להראות על המסך מי כבר הצביעה (בלי מה היא בחרה)</label>\n      </div>\n    </div>\n\n    <p class=\"error\" id=\"setup-error\"></p>\n    <div style=\"text-align:center\">\n      <button class=\"btn primary big\" id=\"btn-create\">יצירת המשחק ←</button>\n    </div>\n  </div>\n</section>\n\n<!-- ===== המשחק – במה ===== -->\n<section id=\"view-game\" hidden>\n  <div class=\"stage closed\" id=\"stage\">\n    <div class=\"spot\"></div>\n    <div class=\"floor\"></div>\n    <div class=\"game-main\" id=\"game-main\"></div>\n    <div class=\"curtain left\"></div>\n    <div class=\"curtain right\"></div>\n    <div class=\"curtain-label\" id=\"curtain-label\"></div>\n    <div class=\"valance\"></div>\n    <div class=\"confetti\" id=\"confetti\"></div>\n    <div class=\"stage-info\">\n      <span id=\"dial-info\"></span>\n      <span class=\"pin-box\">קוד משחק <b id=\"game-pin\"></b></span>\n    </div>\n  </div>\n  <div class=\"controls\" id=\"controls\"></div>\n</section>\n\n<script src=\"/app.js\"></script>\n</body>\n</html>\n"},"/robots.txt":{"type":"text/plain; charset=utf-8","b64":false,"body":"User-agent: *\nDisallow: /\n"},"/sim.html":{"type":"text/html; charset=utf-8","b64":false,"body":"<!DOCTYPE html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"robots\" content=\"noindex, nofollow\" />\n  <title>סימולטור טלפון</title>\n  <link rel=\"stylesheet\" href=\"/style.css\" />\n  <style>\n    .phone { max-width: 340px; margin: 20px auto; background: #222; color: #eee; border-radius: 28px; padding: 22px; }\n    .screen { background: #cfe3c5; color: #1d2a18; border-radius: 10px; padding: 12px; min-height: 150px; font-size: 1rem; }\n    .screen .say { margin-bottom: 6px; }\n    .screen .typed { font-size: 1.8rem; font-weight: 900; direction: ltr; text-align: center; min-height: 2.4rem; }\n    .keys { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 16px; }\n    .keys button { background: #444; color: #fff; border: 0; border-radius: 12px; padding: 14px; font-size: 1.4rem; font-weight: 700; cursor: pointer; }\n    .keys button:active { background: #666; }\n    .raw { direction: ltr; text-align: left; font-family: monospace; font-size: .8rem; white-space: pre-wrap; word-break: break-all; color: var(--muted); }\n  </style>\n</head>\n<body>\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <h1 class=\"brand-title\" style=\"font-size:1.8rem\">סימולטור טלפון</h1>\n    <p class=\"sub\">מדמה שיחה למערכת הטלפונית בדיוק כמו טלפון כשר. אפשר לפתוח כמה לשוניות כדי לדמות כמה משתתפות.</p>\n    <div class=\"card\">\n      <label>מתקשרת מהמספר:\n        <select id=\"who\"></select>\n      </label>\n      <div class=\"row\" style=\"margin-top:10px\">\n        <button class=\"btn primary\" id=\"btn-call\">📞 חיוג</button>\n        <button class=\"btn danger\" id=\"btn-hang\">ניתוק</button>\n      </div>\n    </div>\n    <div class=\"phone\">\n      <div class=\"screen\" id=\"screen\"><div class=\"say\">לחצי \"חיוג\" כדי להתחיל</div></div>\n      <div class=\"keys\" id=\"keys\"></div>\n      <div class=\"row\" style=\"margin-top:10px;justify-content:center\">\n        <button class=\"btn small\" id=\"btn-timeout\" title=\"מדמה מצב שלא הקישו כלום עד שנגמר זמן ההמתנה\">⌛ לא הקשתי (המתנה)</button>\n      </div>\n    </div>\n    <details><summary class=\"muted\">מה השרת שולח לימות המשיח (לבדיקה טכנית)</summary><div class=\"raw\" id=\"raw\"></div></details>\n  </div>\n<script>\nconst $ = (s) => document.querySelector(s);\nconst token = localStorage.getItem('seker_token');\nconst gameId = new URLSearchParams(location.search).get('game');\nlet vals = null, varName = null, typed = '', callId = null;\n\n$('#keys').innerHTML = ['1','2','3','4','5','6','7','8','9','*','0','#'].map(k => `<button data-k=\"${k}\">${k}</button>`).join('');\n\nasync function loadPlayers() {\n  const r = await fetch(`/api/games/${gameId}`, { headers: { authorization: 'Bearer ' + token } });\n  const s = await r.json();\n  const opts = s.players.map(p => `<option value=\"${p.hasPhone ? 'p' + p.num : ''}\">${p.num}. ${p.name}${p.hasPhone ? '' : ' (אין טלפון רשום)'}</option>`);\n  $('#who').innerHTML = opts.join('') + '<option value=\"\">מספר לא מזוהה / חסוי</option>';\n  window._players = s.players;\n}\n\nasync function send() {\n  const pick = $('#who').value;\n  // הטלפון האמיתי לא נחשף לדפדפן; השרת מוצא אותו לפי מספר המשתתפת\n  const res = await fetch(`/api/games/${gameId}/sim`, {\n    method: 'POST',\n    headers: { 'content-type': 'application/json', authorization: 'Bearer ' + token },\n    body: JSON.stringify({ params: vals, simPlayer: pick ? Number(pick.slice(1)) : null }),\n  });\n  const data = await res.json();\n  if (!res.ok) return show([data.error || 'שגיאה'], true);\n  $('#raw').textContent = data.response;\n  const parts = data.response.split('&').filter(Boolean);\n  const lines = [];\n  varName = null;\n  let hang = false;\n  for (const p of parts) {\n    const [cmd, ...rest] = p.split('=');\n    if (cmd === 'id_list_message') lines.push(...speak(rest.join('=')));\n    if (cmd === 'read') { lines.push(...speak(rest[0])); varName = rest[1].split(',')[0]; }\n    if (cmd === 'go_to_folder' && rest[0] === 'hangup') hang = true;\n  }\n  if (hang) { lines.push('— השיחה נותקה —'); callId = null; }\n  show(lines);\n}\n\nfunction speak(m) {\n  return m.split('.').map(x => x.startsWith('t-') ? x.slice(2) : x.startsWith('n-') ? x.slice(2) : x).join(' ').split('\\n');\n}\n\nfunction show(lines) {\n  typed = '';\n  $('#screen').innerHTML = lines.map(l => `<div class=\"say\">🔊 ${l.replace(/</g, '&lt;')}</div>`).join('') + '<div class=\"typed\" id=\"typed\"></div>';\n}\n\n$('#btn-call').onclick = async () => {\n  callId = 'sim-' + Math.random().toString(36).slice(2);\n  vals = { ApiCallId: callId, ApiDID: '0770000000', ApiExtension: '1' };\n  await send();\n};\n$('#btn-hang').onclick = async () => {\n  if (!callId) return;\n  vals.hangup = 'yes';\n  await send();\n  show(['— השיחה נותקה —']);\n  callId = null;\n};\n$('#btn-timeout').onclick = async () => {\n  if (!callId || !varName) return;\n  vals[varName] = 'None';\n  await send();\n};\n$('#keys').onclick = async (e) => {\n  const k = e.target.dataset.k;\n  if (!k || !callId || !varName) return;\n  if (k === '#') {\n    vals[varName] = typed;\n    await send();\n    return;\n  }\n  if (k === '*') { typed = ''; } else typed += k;\n  $('#typed').textContent = typed;\n  // ימות המשיח מסיימת אוטומטית כשמגיעים למספר הספרות המקסימלי\n  const max = Number(($('#raw').textContent.match(/read=[^=]*=[^,]+,[^,]*,(\\d+)/) || [])[1] || 99);\n  if (typed.length >= max) { vals[varName] = typed; await send(); }\n};\n\nif (!token || !gameId) show(['צריך לפתוח את הסימולטור מתוך מסך המשחק']);\nelse loadPlayers();\n</script>\n</body>\n</html>\n"},"/style.css":{"type":"text/css; charset=utf-8","b64":false,"body":"@import url('https://fonts.googleapis.com/css2?family=Rubik:wght@400;500;700;900&family=Suez+One&display=swap');\n\n:root {\n  --bg: #fbf7f4;\n  --card: #ffffff;\n  --ink: #2b2233;\n  --muted: #7a6f80;\n  --line: #ece4e8;\n  --brand: #7b3fa0;\n  --brand-2: #c2477e;\n  --brand-soft: #f3e9f8;\n  --ok: #2f9e6b;\n  --warn: #d98a1c;\n  --danger: #c93c3c;\n  --radius: 16px;\n  --shadow: 0 6px 24px rgba(60, 20, 80, 0.08);\n}\n\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  font-family: 'Rubik', system-ui, 'Segoe UI', Arial, sans-serif;\n  background: var(--bg);\n  color: var(--ink);\n  direction: rtl;\n  font-size: 17px;\n  line-height: 1.5;\n}\n[hidden] { display: none !important; }\n\n.wrap { max-width: 1100px; margin: 0 auto; padding: 24px 20px 80px; }\n.center-page { min-height: 100vh; display: grid; place-items: center; padding: 20px; }\n\n.brand-title {\n  font-weight: 900;\n  font-size: 2.4rem;\n  margin: 0 0 4px;\n  background: linear-gradient(90deg, var(--brand), var(--brand-2));\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n.sub { color: var(--muted); margin: 0 0 20px; }\n\n.card {\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n  padding: 22px;\n  margin-bottom: 18px;\n}\n.card h2 { margin: 0 0 12px; font-size: 1.3rem; }\n.card h2 .step {\n  display: inline-grid; place-items: center;\n  width: 30px; height: 30px; border-radius: 50%;\n  background: var(--brand); color: #fff; font-size: 1rem; margin-left: 8px;\n}\n\ninput, select, textarea, button { font: inherit; }\ninput[type=text], input[type=tel], input[type=password], input[type=number], select, textarea {\n  width: 100%;\n  padding: 10px 12px;\n  border: 1.5px solid var(--line);\n  border-radius: 10px;\n  background: #fff;\n  color: var(--ink);\n}\ninput:focus, select:focus, textarea:focus { outline: none; border-color: var(--brand); }\ninput.ltr { direction: ltr; text-align: right; }\n\n.btn {\n  border: 0;\n  border-radius: 12px;\n  padding: 10px 18px;\n  background: var(--brand-soft);\n  color: var(--brand);\n  font-weight: 700;\n  cursor: pointer;\n  transition: transform .08s, filter .15s;\n}\n.btn:hover { filter: brightness(0.96); }\n.btn:active { transform: scale(0.98); }\n.btn:disabled { opacity: .5; cursor: not-allowed; }\n.btn.primary { background: linear-gradient(90deg, var(--brand), var(--brand-2)); color: #fff; }\n.btn.big { padding: 14px 28px; font-size: 1.2rem; }\n.btn.danger { background: #fbeaea; color: var(--danger); }\n.btn.ghost { background: transparent; color: var(--muted); }\n.btn.small { padding: 6px 12px; font-size: .9rem; }\n\n.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }\n.grow { flex: 1; }\n.muted { color: var(--muted); }\n.error { color: var(--danger); font-weight: 500; min-height: 1.5em; }\n.note { background: #fff8e8; border: 1px solid #f3e1b5; border-radius: 12px; padding: 10px 14px; color: #7a5a14; }\n\n/* טבלת משתתפות */\n.players-grid { display: grid; grid-template-columns: 44px 1fr 1fr; gap: 8px 10px; align-items: center; }\n.players-grid .num {\n  width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center;\n  background: var(--brand-soft); color: var(--brand); font-weight: 700;\n}\n.players-grid .head { font-size: .9rem; color: var(--muted); }\n\n/* רשימת שאלות */\n.q-tools { margin-bottom: 12px; }\n.q-list { display: flex; flex-direction: column; gap: 8px; max-height: 520px; overflow: auto; padding-left: 4px; }\n.q-item {\n  display: grid; grid-template-columns: 28px 1fr auto; gap: 10px; align-items: start;\n  padding: 10px 12px; border: 1px solid var(--line); border-radius: 12px; background: #fff;\n}\n.q-item.off { opacity: .55; background: #faf8f9; }\n.q-item input[type=checkbox] { width: 20px; height: 20px; margin-top: 10px; accent-color: var(--brand); }\n.q-item .q-meta { font-size: .85rem; color: var(--muted); margin-top: 4px; }\n.q-item .q-edit { display: flex; flex-direction: column; gap: 6px; }\n.tag { display: inline-block; padding: 1px 8px; border-radius: 99px; background: var(--brand-soft); color: var(--brand); font-size: .8rem; margin-left: 6px; }\n.tag.opt { background: #e7f3ff; color: #2463a6; }\n\n.settings-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 14px; }\n.settings-grid label { display: flex; gap: 8px; align-items: center; }\n.settings-grid input[type=checkbox] { width: 20px; height: 20px; accent-color: var(--brand); }\n\n/* ================= מסך המשחק – במה ================= */\n\n#view-game { background: #0d0612; min-height: 100vh; display: flex; flex-direction: column; }\n\n.stage {\n  --gold: #f6c453;\n  --gold-2: #d99a2b;\n  --velvet: #8e1022;\n  position: relative;\n  flex: 1;\n  min-height: calc(100vh - 66px);\n  overflow: hidden;\n  color: #fff;\n  background:\n    radial-gradient(ellipse 70% 55% at 50% 38%, #3b1d52 0%, #1d0d2a 55%, #0d0612 100%);\n  isolation: isolate;\n}\n\n/* אלומת זרקור */\n.spot {\n  position: absolute; inset: 0; pointer-events: none; z-index: 0;\n  background:\n    conic-gradient(from 180deg at 50% -10%, transparent 160deg, rgba(255, 236, 190, .13) 172deg, rgba(255, 236, 190, .2) 180deg, rgba(255, 236, 190, .13) 188deg, transparent 200deg);\n  filter: blur(6px);\n}\n.stage.closed .spot { opacity: .35; }\n\n/* רצפת עץ */\n.floor {\n  position: absolute; left: 0; right: 0; bottom: 0; height: 15%; z-index: 0;\n  background:\n    linear-gradient(180deg, rgba(0,0,0,.55), rgba(0,0,0,0) 30%),\n    repeating-linear-gradient(90deg, #5a3417 0 120px, #4c2b12 120px 122px),\n    #5a3417;\n  box-shadow: inset 0 10px 30px rgba(0,0,0,.6);\n}\n.floor::before { /* קו קדמת הבמה */\n  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 6px;\n  background: linear-gradient(90deg, var(--gold-2), var(--gold), var(--gold-2));\n}\n\n/* תוכן הבמה */\n.game-main {\n  position: relative; z-index: 1;\n  padding: 120px 9% 140px;\n  max-width: 1500px; margin: 0 auto;\n}\n.game-main.enter > * { animation: rise .7s cubic-bezier(.2,.8,.2,1) both; }\n.game-main.enter > *:nth-child(2) { animation-delay: .12s; }\n.game-main.enter > *:nth-child(3) { animation-delay: .24s; }\n.game-main.enter > *:nth-child(4) { animation-delay: .36s; }\n@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }\n\n/* וילונות */\n.curtain {\n  position: absolute; top: 0; bottom: 0; width: 51%; z-index: 5;\n  background:\n    linear-gradient(180deg, rgba(0,0,0,.35), rgba(0,0,0,0) 18%, rgba(0,0,0,0) 80%, rgba(0,0,0,.45)),\n    repeating-linear-gradient(90deg,\n      #5e0a16 0px, #8e1022 18px, #b51c33 34px, #8e1022 52px, #5e0a16 70px);\n  box-shadow: inset 0 0 60px rgba(0,0,0,.55);\n  transition: transform 1.1s cubic-bezier(.65,0,.35,1);\n}\n.curtain.left  { left: 0;  transform-origin: left center; }\n.curtain.right { right: 0; transform-origin: right center; }\n.curtain::after { /* שוליים מוזהבים בתחתית */\n  content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 14px;\n  background: repeating-linear-gradient(90deg, var(--gold) 0 6px, var(--gold-2) 6px 12px);\n  opacity: .9;\n}\n/* פתוח: הווילון נאסף לצדדים ומשאיר רצועה של בד */\n.stage:not(.closed) .curtain.left  { transform: translateX(-88%) scaleX(1); }\n.stage:not(.closed) .curtain.right { transform: translateX(88%)  scaleX(1); }\n.stage.no-anim .curtain, .stage.no-anim .curtain-label { transition: none !important; }\n\n/* קישוט עליון (ולאנס) */\n.valance {\n  position: absolute; top: 0; left: 0; right: 0; height: 74px; z-index: 7;\n  background:\n    radial-gradient(circle at 50% 0, #a3172b 0 44px, transparent 45px) 0 30px / 90px 50px repeat-x,\n    linear-gradient(180deg, #6d0c1a, #a3172b 70%, #7c0e1e);\n  background-size: 90px 88px, 100% 46px;\n  background-repeat: repeat-x, no-repeat;\n  filter: drop-shadow(0 8px 10px rgba(0,0,0,.5));\n}\n.valance::after {\n  content: ''; position: absolute; top: 44px; left: 0; right: 0; height: 5px;\n  background: linear-gradient(90deg, var(--gold-2), var(--gold), var(--gold-2));\n}\n\n/* כיתוב על הווילון */\n.curtain-label {\n  position: absolute; inset: 80px 6% 90px; z-index: 6;\n  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px;\n  text-align: center; pointer-events: none;\n  opacity: 0; transform: scale(.92);\n  transition: opacity .5s, transform .5s;\n}\n.stage.closed .curtain-label { opacity: 1; transform: none; transition-delay: .55s; }\n.marquee {\n  font-family: 'Suez One', 'Rubik', serif;\n  font-size: clamp(2.8rem, 7vw, 6rem); line-height: 1.05;\n  color: var(--gold);\n  text-shadow: 0 2px 0 #7a4b06, 0 0 24px rgba(246,196,83,.55), 0 6px 18px rgba(0,0,0,.6);\n}\n.marquee.big { font-size: clamp(6rem, 16vw, 13rem); }\n.curtain-sub { font-size: clamp(1.3rem, 2.4vw, 2rem); font-weight: 700; color: #ffe9c2; text-shadow: 0 2px 8px rgba(0,0,0,.6); }\n.curtain-sub b { color: var(--gold); letter-spacing: 3px; }\n.curtain-sub.small { font-size: 1.15rem; font-weight: 500; opacity: .9; }\n.lobby-chips { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 1000px; margin: 10px 0; }\n.lchip {\n  background: rgba(0,0,0,.35); border: 1.5px solid rgba(246,196,83,.35); color: #ffe9c2;\n  padding: 8px 16px; border-radius: 99px; font-size: 1.2rem; font-weight: 500; transition: all .3s;\n}\n.lchip b { color: var(--gold); margin-left: 4px; }\n.lchip.on { background: rgba(246,196,83,.92); color: #3a2205; border-color: var(--gold); box-shadow: 0 0 18px rgba(246,196,83,.6); }\n.lchip.on b { color: #7a1020; }\n\n/* פס מידע תחתון */\n.stage-info {\n  position: absolute; left: 0; right: 0; bottom: 0; z-index: 8;\n  display: flex; justify-content: center; gap: 30px; align-items: center; flex-wrap: wrap;\n  padding: 10px 20px; font-size: 1.15rem; color: #ffe9c2;\n  background: linear-gradient(0deg, rgba(0,0,0,.75), rgba(0,0,0,0));\n}\n.stage-info b { color: var(--gold); font-size: 1.35rem; direction: ltr; display: inline-block; }\n.pin-box b { letter-spacing: 4px; margin-right: 6px; }\n\n/* שאלה */\n.q-head { display: flex; justify-content: space-between; align-items: center; gap: 20px; }\n.q-counter { color: var(--gold); font-weight: 700; font-size: 1.3rem; letter-spacing: .5px; }\n.q-title {\n  font-family: 'Suez One', 'Rubik', serif;\n  font-size: clamp(2.2rem, 4.6vw, 4rem); line-height: 1.2; margin: 8px 0 30px;\n  text-shadow: 0 0 30px rgba(255,220,150,.25), 0 4px 12px rgba(0,0,0,.6);\n}\n.q-title.small { font-size: clamp(1.6rem, 3vw, 2.6rem); margin-bottom: 14px; opacity: .9; }\n\n.options { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 14px; }\n.opt {\n  display: flex; align-items: center; gap: 14px;\n  background: linear-gradient(180deg, rgba(255,255,255,.12), rgba(255,255,255,.05));\n  border: 1px solid rgba(246,196,83,.3);\n  border-radius: 16px; padding: 12px 16px; font-size: 1.5rem; font-weight: 500;\n  box-shadow: 0 8px 24px rgba(0,0,0,.35); backdrop-filter: blur(4px);\n}\n.opt .n {\n  flex: none; min-width: 54px; height: 54px; border-radius: 50%; display: grid; place-items: center;\n  background: radial-gradient(circle at 35% 30%, #ffe7a3, var(--gold) 45%, var(--gold-2));\n  color: #4a1a06; font-weight: 900; font-size: 1.6rem; box-shadow: 0 0 0 3px rgba(0,0,0,.25), 0 0 16px rgba(246,196,83,.4);\n}\n.opt .lbl { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n.status-line { display: flex; gap: 26px; align-items: center; font-size: 1.35rem; margin-top: 26px; flex-wrap: wrap; }\n.vote-count b { color: var(--gold); font-size: 1.8rem; }\n.hint { color: #c9b8d6; font-size: 1.1rem; }\n.voters { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px; }\n.chip { padding: 6px 14px; border-radius: 99px; background: rgba(255,255,255,.08); color: #b9a8c6; font-weight: 500; transition: all .3s; }\n.chip.on { background: rgba(80, 200, 140, .22); color: #8ff0c0; }\n.chip.on::before { content: '✓ '; }\n\n/* טיימר עגול */\n.timer-ring { position: relative; width: 130px; height: 130px; flex: none; }\n.timer-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }\n.timer-ring circle { fill: rgba(0,0,0,.35); stroke-width: 10; }\n.timer-ring .track { stroke: rgba(255,255,255,.12); }\n.timer-ring .prog { fill: none; stroke: var(--gold); stroke-linecap: round; transition: stroke-dashoffset .25s linear, stroke .3s; filter: drop-shadow(0 0 6px rgba(246,196,83,.7)); }\n.timer-ring .num {\n  position: absolute; inset: 0; display: grid; place-items: center;\n  font-family: 'Suez One', 'Rubik', serif; font-size: 3rem; color: #fff;\n}\n.timer-ring.low .prog { stroke: #ff4d5e; filter: drop-shadow(0 0 8px rgba(255,77,94,.9)); }\n.timer-ring.low .num { color: #ff8a95; animation: pulse 1s infinite; }\n.timer-ring.done .num { font-size: 2.6rem; animation: shake .5s 2; }\n@keyframes pulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.22); } }\n@keyframes shake { 0%,100% { transform: rotate(0); } 25% { transform: rotate(-12deg); } 75% { transform: rotate(12deg); } }\n\n/* תוצאות */\n.winner-banner {\n  text-align: center; margin: 6px 0 26px;\n  display: flex; flex-direction: column; align-items: center; animation: pop .8s cubic-bezier(.2,1.4,.4,1) both .2s;\n}\n.winner-banner .crown { font-size: 3.4rem; line-height: 1; animation: float 2s ease-in-out infinite; }\n.winner-banner .wname {\n  font-family: 'Suez One', 'Rubik', serif; font-size: clamp(2.6rem, 6vw, 5rem); color: var(--gold);\n  text-shadow: 0 2px 0 #7a4b06, 0 0 30px rgba(246,196,83,.6);\n}\n@keyframes pop { from { transform: scale(.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }\n@keyframes float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }\n\n.bars { display: flex; flex-direction: column; gap: 12px; }\n.bar-row { display: grid; grid-template-columns: 220px 1fr 60px; gap: 14px; align-items: center; font-size: 1.45rem; }\n.bar-row .lbl { font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.bar-track { background: rgba(255,255,255,.08); border-radius: 12px; height: 46px; overflow: hidden; }\n.bar-fill {\n  height: 100%; width: 0; border-radius: 12px;\n  background: linear-gradient(90deg, #c2477e, #7b3fa0);\n  transition: width 1.3s cubic-bezier(.2,.8,.2,1);\n}\n.bar-row.win .bar-fill { background: linear-gradient(90deg, var(--gold-2), var(--gold), #ffe7a3); box-shadow: 0 0 20px rgba(246,196,83,.5); }\n.bar-row.win .lbl { color: var(--gold); }\n.bar-row .cnt { font-family: 'Suez One', 'Rubik', serif; font-size: 1.8rem; }\n.no-votes { color: #a996b8; margin-top: 18px; font-size: 1.1rem; }\n\n/* סיכום */\n.summary { display: flex; flex-direction: column; gap: 10px; }\n.sum-row {\n  display: flex; justify-content: space-between; gap: 16px; font-size: 1.2rem;\n  background: rgba(255,255,255,.07); border: 1px solid rgba(246,196,83,.2);\n  border-radius: 12px; padding: 12px 18px; animation: rise .6s both;\n}\n.sum-row b { color: var(--gold); }\n.sum-row small { color: #b9a8c6; }\n\n/* קונפטי */\n.confetti { position: absolute; inset: 0; pointer-events: none; z-index: 9; overflow: hidden; }\n.confetti i { position: absolute; top: -20px; border-radius: 2px; animation: fall linear forwards; }\n@keyframes fall {\n  0% { transform: translateY(0) rotate(0); opacity: 1; }\n  100% { transform: translateY(105vh) rotate(720deg); opacity: .8; }\n}\n\n/* כפתורי שליטה */\n.controls {\n  position: sticky; bottom: 0; z-index: 20;\n  background: #160a1f; border-top: 1px solid #3a2348;\n  padding: 10px 20px; display: flex; gap: 10px; flex-wrap: wrap; justify-content: center;\n}\n.controls .btn { background: #2b1838; color: #e8d9f2; }\n.controls .btn.primary { background: linear-gradient(90deg, var(--gold-2, #d99a2b), #f6c453); color: #3a1a04; }\n.controls .btn.danger { background: #3a1420; color: #ff9aa6; }\n.controls .btn.ghost { background: transparent; color: #a996b8; }\n\n@media (max-width: 800px) {\n  .game-main { padding: 100px 14% 130px; }\n  .bar-row { grid-template-columns: 110px 1fr 40px; font-size: 1.1rem; }\n  .timer-ring { width: 90px; height: 90px; }\n  .timer-ring .num { font-size: 2rem; }\n}\n\ntable.admin { width: 100%; border-collapse: collapse; }\ntable.admin th, table.admin td { padding: 8px; border-bottom: 1px solid var(--line); text-align: right; vertical-align: middle; }\ntable.admin th { color: var(--muted); font-weight: 500; font-size: .9rem; }\n.code-txt { font-family: monospace; font-size: 1.15rem; font-weight: 700; direction: ltr; display: inline-block; }\n\n@media (max-width: 700px) {\n  .players-grid { grid-template-columns: 36px 1fr; }\n  .players-grid .phone-cell { grid-column: 2; }\n  .players-grid .head.ph { display: none; }\n}\n"}};
